#include "ir_led_task.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/rmt_tx.h"
#include "esp_log.h"

#include "message_type.h"

/*
 * Olympia Infoglobe IR link.
 *
 * Waveform (unchanged from the original LEDC/GPTimer implementation):
 *   - 38.54 kHz carrier, 50 % duty
 *   - 1 ms per bit, bytes sent MSB first, back to back
 *   - bit 0 = carrier ON, bit 1 = LED off; idle = LED off
 *
 * The whole message is generated by the RMT peripheral from its own memory:
 * bit timing comes from the 80 MHz APB clock divided down in hardware, and the
 * carrier is RMT's built-in modulator. The CPU only hands the frame over.
 * Wi-Fi, flash writes, interrupt latency and task scheduling can no longer
 * stretch or shorten bits, and the last bit always gets its full 1 ms.
 *
 * The previous design toggled LEDC duty from a 1 kHz GPTimer ISR, which
 *   (a) could be delayed by milliseconds while the flash cache was disabled
 *       (the ISR was not IRAM-safe), stretching bits -> garbled characters;
 *   (b) let the task turn the carrier off as soon as the last bit started,
 *       so the final bit could be cut short;
 *   (c) called ledc_set_duty() from the ISR, whose read-modify-write of the
 *       ESP32 LEDC conf1 register could re-arm duty_start forever, hanging
 *       ledc_update_duty() until the interrupt watchdog reset the chip.
 */

static const char *TAG = "IR_TASK";

#define IR_RESOLUTION_HZ   1000000                 // 1 tick = 1 us
#define IR_BIT_US          1000                    // 1 ms per bit
#define IR_CARRIER_HZ      38540
#define IR_MAX_RUN_US      32000                   // < 32767-tick symbol limit
#define IR_LEVEL_CARRIER   1                       // RMT high = carrier on
#define IR_LEVEL_OFF       0

/* Worst case (alternating bits) needs one half-symbol per bit. Keep the whole
 * frame inside RMT RAM (4 x 64-symbol blocks) so no refill ISR is involved. */
#define IR_MEM_SYMBOLS     256
#define IR_MAX_HALVES      (MAX_MESSAGE_LEN * 8)
#define IR_MAX_SYMBOLS     ((IR_MAX_HALVES + 1) / 2 + 1)

_Static_assert(IR_MAX_SYMBOLS < IR_MEM_SYMBOLS, "IR frame must fit in RMT memory");

static rmt_channel_handle_t s_tx_chan;
static rmt_encoder_handle_t s_copy_encoder;
static rmt_symbol_word_t s_symbols[IR_MAX_SYMBOLS];

/* Turn bytes into RMT symbols: runs of equal bits become one level/duration
 * pair (split at IR_MAX_RUN_US), two pairs per symbol. Returns symbol count. */
static size_t build_symbols(const uint8_t *data, size_t len)
{
    size_t halves = 0;
    int run_level = -1;
    uint32_t run_us = 0;

    #define EMIT(level_, dur_) do {                                   \
        rmt_symbol_word_t *s_ = &s_symbols[halves / 2];               \
        if ((halves & 1) == 0) {                                      \
            s_->level0 = (level_); s_->duration0 = (dur_);            \
            s_->level1 = IR_LEVEL_OFF; s_->duration1 = 0;             \
        } else {                                                      \
            s_->level1 = (level_); s_->duration1 = (dur_);            \
        }                                                             \
        halves++;                                                     \
    } while (0)

    for (size_t i = 0; i < len; i++) {
        for (int b = 7; b >= 0; b--) {
            int level = (data[i] & (1u << b)) ? IR_LEVEL_OFF : IR_LEVEL_CARRIER;
            if (level != run_level || run_us + IR_BIT_US > IR_MAX_RUN_US) {
                if (run_level >= 0) {
                    EMIT(run_level, run_us);
                }
                run_level = level;
                run_us = 0;
            }
            run_us += IR_BIT_US;
        }
    }
    if (run_level >= 0) {
        EMIT(run_level, run_us);
    }
    #undef EMIT

    /* An odd half count leaves duration1 = 0 in the last symbol, which RMT
     * treats as end-of-frame; eot_level keeps the LED off afterwards. */
    return (halves + 1) / 2;
}

static void ir_init(void)
{
    rmt_tx_channel_config_t tx_cfg = {
        .gpio_num = LED_PIN,
        .clk_src = RMT_CLK_SRC_DEFAULT,
        .resolution_hz = IR_RESOLUTION_HZ,
        .mem_block_symbols = IR_MEM_SYMBOLS,
        .trans_queue_depth = 1,
        .flags.init_level = IR_LEVEL_OFF,
    };
    ESP_ERROR_CHECK(rmt_new_tx_channel(&tx_cfg, &s_tx_chan));

    rmt_carrier_config_t carrier_cfg = {
        .frequency_hz = IR_CARRIER_HZ,
        .duty_cycle = 0.5f,
        .flags.polarity_active_low = false,   // carrier on the high level
    };
    ESP_ERROR_CHECK(rmt_apply_carrier(s_tx_chan, &carrier_cfg));

    rmt_copy_encoder_config_t enc_cfg = {};
    ESP_ERROR_CHECK(rmt_new_copy_encoder(&enc_cfg, &s_copy_encoder));
    ESP_ERROR_CHECK(rmt_enable(s_tx_chan));
}

static void ir_send(const uint8_t *data, size_t len)
{
    if (len > MAX_MESSAGE_LEN) {
        ESP_LOGW(TAG, "Message of %u bytes truncated to %d", (unsigned)len, MAX_MESSAGE_LEN);
        len = MAX_MESSAGE_LEN;
    }
    size_t n = build_symbols(data, len);
    rmt_transmit_config_t tx = {
        .loop_count = 0,
        .flags.eot_level = IR_LEVEL_OFF,
    };
    ESP_ERROR_CHECK(rmt_transmit(s_tx_chan, s_copy_encoder, s_symbols,
                                 n * sizeof(rmt_symbol_word_t), &tx));
    // Frame length is at most 32 bytes * 8 ms = 256 ms; 1 s is a hard ceiling.
    esp_err_t err = rmt_tx_wait_all_done(s_tx_chan, 1000);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "IR frame did not finish: %s", esp_err_to_name(err));
    }
}

void ir_tx_task(void *pvParameters)
{
    QueueHandle_t display_queue = (QueueHandle_t)(pvParameters);
    ir_init();

    msg_buffer_t received;
    while (1) {
        if (pop_buffer_from_queue(display_queue, &received) != pdPASS) {
            continue;
        }
        vTaskDelay(pdMS_TO_TICKS(100));   // inter-message gap, as before

        printf("Received buffer of size %d: ", received.size);
        for (size_t i = 0; i < received.size; i++) {
            printf("%d ", received.buffer[i]);
        }
        printf("\n");

        ESP_LOGI(TAG, "TX Begin!");
        ir_send(received.buffer, received.size);
        ESP_LOGI(TAG, "TX Complete!");

        free(received.buffer);
    }
}
